from ute_common_converter.to_number import to_int

from ute_btssm.executor import Executor

from ..config import SessionConfig, ENBConfig

from .base import BaseInterface

import time
import logging
from random import randint
from ..commandexecutor.cl_executor import ClToolExecutor
from ..commandexecutor.remote_executor import RemoteExecutor
from ..thread import Thread
from ..templatesession import btsconnmanager


LOG = logging.getLogger(__name__)


class SetupInterface(BaseInterface):
    def setup_btssm(self, jars_path=None, install_location=None, host_ip='127.0.0.1', log_path='/tmp', timeout=None,
                    ne=ENBConfig.trs_ip, pw=ENBConfig.pw, rc_only=False, **kwargs):
        """Setup BTSSM library.

        Library uses SSHClient to execute java commands.

        :param string  jars_path:         Path to the jar files provided by BTSCommandLineTools. If None, built-in BTSCommandLineTools are used.
        :param string  install_location:  Path where BTS SM is (or should be) installed.
        :param string  host_ip:           IP Address of remote/local host.
        :param string  log_path:          Path to the directory where log files and other downloaded files_ will be stored
        :param         timeout:           Execution timeout in case java application operates too long.
                                          Can be specified in human format like 5s, 10minutes, 1min 5s.
                                          Timeout is assumed to be in seconds if value is integer or float.
        :param string  ne:                BTS TRS IP address. Default value for all keywords of ute_btssm.
        :param string  pw:                Default credentials for BTS Site Manager (TRS) in all keywords of ute_btssm.
                                          The format is username:password.
        :param bool    rc_only:           Specify if exception will only show the error code.
        |

        :Supported SSH parameters are available via kwargs:
            * **ssh_username**   (string)  - Username valid for SSH authentication. Default is 'ute'.
            * **ssh_password**   (string)  - Password valid for SSH authentication. Default is 'ute'.
            * **ssh_port**       (integer) - SSH service port available on specified machine. Default is 22.
            * **ssh_prompt**     (string)  - SH prompt available after log in. Default is '$ '.

        :Other supported parameters available via kwargs:
            * **nolog**          (bool)    - Specify to prevent tool from creating log file for all keywords.
                                             This can be overridden in CLI tool keywords interface.
        It is possible to change the kwargs parameters by using syntax like in the example below:

        ::

                Some keyword     ssh_username=test_user    ssh_password=test_pass    ssh_port=22    ssh_prompt=\$
        """
        alias = kwargs.get('alias')
        alias = alias.strip() if alias else None
        host_ip = host_ip if host_ip else "127.0.0.1"
        jars_path = jars_path if jars_path else '/opt/btssm_cli_tools/lib'
        config = SessionConfig(jars_path=jars_path,
                               install_location=install_location,
                               host_ip=host_ip,
                               log_path=log_path,
                               timeout=self._convert_to_secs(timeout),
                               ssh_username=kwargs.get('ssh_username', 'ute'),
                               ssh_password=kwargs.get('ssh_password', 'ute'),
                               ssh_port=to_int(kwargs.get('ssh_port', 22)),
                               ssh_prompt=kwargs.get('ssh_prompt', '$ '),
                               nolog=kwargs.get('nolog', None),
                               trs_ip=ne,
                               pw=pw,
                               alias=alias,
                               rc_only=rc_only)
        self.command_store.add(ClToolExecutor(config), alias)
        self._prepare_log_path(log_path=log_path, config=config)

    def setup_remote_tool(self, jars_path=None, install_location=None, host_ip='127.0.0.1', log_path='/tmp', timeout=None,
                          ne=ENBConfig.trs_ip, pw=ENBConfig.pw, **kwargs):
        """Setup Remote tool of BTSSM library.

        Library uses SSHClient to execute java commands.

        :param string  jars_path:         Path to the jar files provided by BTSCommandLineTools. If None, built-in BTSCommandLineTools are used.
        :param string  install_location:  Path where BTS SM is (or should be) installed.
        :param string  host_ip:           IP Address of remote/local host.
        :param string  log_path:          Path to the directory where log files and other downloaded files_ will be stored
        :param         timeout:           Execution timeout in case java application operates too long.
                                          Can be specified in human format like 5s, 10minutes, 1min 5s.
                                          Timeout is assumed to be in seconds if value is integer or float.

        |

        :Supported SSH parameters are available via kwargs:
            * **ssh_username**   (string)  - Username valid for SSH authentication. Default is 'ute'.
            * **ssh_password**   (string)  - Password valid for SSH authentication. Default is 'ute'.
            * **ssh_port**       (integer) - SSH service port available on specified machine. Default is 22.
            * **ssh_prompt**     (string)  - SH prompt available after log in. Default is '$ '.

        It is possible to change the kwargs parameters by using syntax like in the example below:

        ::

                Some keyword     ssh_username=test_user    ssh_password=test_pass    ssh_port=22    ssh_prompt=\$
        """
        alias, config, rpc_port, rpc_session = self._initialize_remote_tool_parameters(jars_path, install_location, host_ip, log_path, timeout,
                                                                                       ne, pw, **kwargs)
        cmd = rpc_session.cmd_builder.cl_tool.build(op="remote", params={"ne": 'local', "rpcport": rpc_port})
        self._start_rpc_thread(alias=alias, rpc_session=rpc_session, command=cmd)
        self._prepare_log_path(log_path=log_path, config=config)

    def setup_remote_tool_with_readonly_access(self, jars_path=None, install_location=None, host_ip='127.0.0.1', log_path='/tmp',
                                               timeout=None, ne=ENBConfig.trs_ip, pw=ENBConfig.pw, **kwargs):
        """Setup Remote tool of BTSSM library with readonly access. This allows multiple BTSSM connections

        Library uses SSHClient to execute java commands.

        :param string  jars_path:         Path to the jar files provided by BTSCommandLineTools. If None, built-in BTSCommandLineTools are used.
        :param string  install_location:  Path where BTS SM is (or should be) installed.
        :param string  host_ip:           IP Address of remote/local host.
        :param string  log_path:          Path to the directory where log files and other downloaded files_ will be stored
        :param         timeout:           Execution timeout in case java application operates too long.
                                          Can be specified in human format like 5s, 10minutes, 1min 5s.
                                          Timeout is assumed to be in seconds if value is integer or float.

        |

        :Supported SSH parameters are available via kwargs:
            * **ssh_username**   (string)  - Username valid for SSH authentication. Default is 'ute'.
            * **ssh_password**   (string)  - Password valid for SSH authentication. Default is 'ute'.
            * **ssh_port**       (integer) - SSH service port available on specified machine. Default is 22.
            * **ssh_prompt**     (string)  - SH prompt available after log in. Default is '$ '.

        It is possible to change the kwargs parameters by using syntax like in the example below:

        ::

                Some keyword     ssh_username=test_user    ssh_password=test_pass    ssh_port=22    ssh_prompt=\$
        """
        alias, config, rpc_port, rpc_session = self._initialize_remote_tool_parameters(jars_path, install_location, host_ip, log_path, timeout,
                                                                                       ne, pw, **kwargs)
        cmd = rpc_session.cmd_builder.cl_tool.build(op="remote", params={"ne": 'local', "rpcport": rpc_port, "conntype": "read-only"})
        self._start_rpc_thread(alias=alias, rpc_session=rpc_session, command=cmd)
        self._prepare_log_path(log_path=log_path, config=config)

    def teardown_btssm(self, **kwargs):
        """Clean up the environment and remove library settings."""
        alias = kwargs.get('alias')
        alias = alias.strip() if alias is not None else None
        self.command_store.remove(alias)

    def teardown_remote_tool(self, **kwargs):
        """ Teardown remote tool """
        alias = kwargs.get('alias')
        alias = alias.strip() if alias is not None else None
        remote_executor = self.command_store.get(alias)
        config = remote_executor.get_config()
        remote_executor.execute_command(alias=alias, operation='quit', params={}, log_path=config.log_path, host_ip=config.host_ip)
        remote_executor.rpc_session.disconnect_session()
        self.command_store.remove(alias)

    def _prepare_log_path(self, log_path, config):
        connection = Executor(config.ssh_connection_params, config.ssh_login_params, log_path=log_path, timeout=30)
        connection.connect()
        connection.run_ignoring_rc('[ ! -d "{}" ] && mkdir -p "{}"'.format(log_path, log_path))
        connection.disconnect()

    def _initialize_remote_tool_parameters(self, jars_path=None, install_location=None,
                                           host_ip='127.0.0.1', log_path='/tmp', timeout=None, ne=ENBConfig.trs_ip, pw=ENBConfig.pw, **kwargs):
        alias = kwargs.get('alias')
        alias = alias.strip() if alias is not None else None
        host_ip = host_ip if host_ip else "127.0.0.1"
        jars_path = jars_path if jars_path else '/opt/btssm_cli_tools/lib'
        timeout = 300 if timeout is None else self._convert_to_secs(timeout)
        config = SessionConfig(jars_path=jars_path,
                               install_location=install_location,
                               host_ip=host_ip,
                               log_path=log_path,
                               timeout=self._convert_to_secs(timeout),
                               ssh_username=kwargs.get('ssh_username', 'ute'),
                               ssh_password=kwargs.get('ssh_password', 'ute'),
                               ssh_port=to_int(kwargs.get('ssh_port', 22)),
                               ssh_prompt=kwargs.get('ssh_prompt', '$ '),
                               nolog=kwargs.get('nolog', None),
                               trs_ip=ne,
                               pw=pw,
                               alias=alias)
        rpc_port = randint(5000, 50000)
        rpc_session = btsconnmanager.BtsConnManager(alias, config, timeout).create_session()
        self.command_store.add(RemoteExecutor(rpc_port=rpc_port, config=config, rpc_session=rpc_session), alias)
        return alias, config, rpc_port, rpc_session

    def _start_rpc_thread(self, alias, rpc_session, command):
        rpc_thread = Thread(alias=alias, exc_callback=self._exception_callback, target=rpc_session.executor.run_via_shell, args=(command, 'remote'))
        rpc_thread.setDaemon(True)
        rpc_thread.start()
        time.sleep(1)

    def _exception_callback(self, alias, exc):
        bts_conn_manager = self.command_store.get(alias)
        bts_conn_manager.set_setup_btssm_exception(exc)
